/**
 *模型名称：保养周天数枚举类型
 *模型KEY:enu_day_of_week
 */
interface DayOfWeek{
  /**
   * 周一
   *
   * @author zyl
   * @type {string}
   */
monday: string,


  /**
   * 周二
   *
   * @author zyl
   * @type {string}
   */
tuesday: string,


  /**
   * 周三
   *
   * @author zyl
   * @type {string}
   */
wednesday: string,


  /**
   * 周四
   *
   * @author zyl
   * @type {string}
   */
thursday: string,


  /**
   * 周五
   *
   * @author zyl
   * @type {string}
   */
friday: string,


  /**
   * 周六
   *
   * @author zyl
   * @type {string}
   */
saturday: string,


  /**
   * 周日
   *
   * @author zyl
   * @type {string}
   */
sunday: string,


}
